import math

def min_Jumps(d: float, length: float) -> int:
    if d == 0:
        return 0
    if length == 0:
        return -1  # can't move if length is zero and d != 0
    if length == d:
        return 1
    if length > d:
        # One jump overshoots, but can we do it in one jump?
        # Since the target is on x-axis, and jump length is fixed,
        # if length > d, one jump can reach the point if we jump at angle 0°
        # But if length > d, one jump can reach (d,0) only if length >= d (true), so 1 jump
        return 1
    # else length < d
    # number of jumps needed is ceiling of d/length
    return math.ceil(d / length)

